        self,
        user_message: str,
        context: LLMContext,
        attachments: Sequence[AttachmentInput] = (),
    ) -> AgentTurn:
        self.calls.append((user_message, context))
        self.attachments_seen.append(list(attachments))
        if self.on_call is not None:
